package ir.neshane.isolationprobe.operations;

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.security.cert.*;
import java.security.spec.ECGenParameterSpec;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import javax.net.ssl.*;

/** Test-only trust and canonical protocol. No shell adapter or production contract. */
public final class LabOperationsTrust {
    static final List<String> NODES=List.of("authority","controller","agent-a","agent-b","executor-a","executor-b");
    static final String PREFIX="ir.neshane.isolationprobe.operations.";
    static final Set<String> REVOKED_PEERS=ConcurrentHashMap.newKeySet();
    static final java.util.concurrent.atomic.AtomicLong REJECTED_PEERS=new java.util.concurrent.atomic.AtomicLong();
    static final class Rejected extends RuntimeException { private static final long serialVersionUID=1L; Rejected(String reason){super(reason);} }
    static void require(boolean value,String reason){if(!value)throw new Rejected(reason);}
    static Map<String,String> map(String... pairs){var m=new TreeMap<String,String>();for(int i=0;i<pairs.length;i+=2)require(m.put(pairs[i],pairs[i+1])==null,"DUPLICATE_FIELD");return m;}
    static String hash(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
    static String b64(byte[] bytes){return Base64.getEncoder().encodeToString(bytes);}
    static byte[] decode(String value){return Base64.getDecoder().decode(value);}
    static byte[] bytes(Map<String,String> m)throws Exception{var out=new ByteArrayOutputStream();write(out,m);return out.toByteArray();}
    static void write(OutputStream stream,Map<String,String> m)throws Exception{var out=new DataOutputStream(stream);require(m.size()<=64,"FIELD_COUNT");out.writeInt(0x4f524631);out.writeInt(m.size());for(var e:new TreeMap<>(m).entrySet())for(String s:List.of(e.getKey(),e.getValue())){byte[] b=s.getBytes(StandardCharsets.UTF_8);require(b.length<=131072,"FIELD_SIZE");out.writeInt(b.length);out.write(b);}out.flush();}
    static Map<String,String> read(InputStream stream)throws Exception{var in=new DataInputStream(stream);require(in.readInt()==0x4f524631,"WIRE_VERSION");int count=in.readInt();require(count>=0&&count<=64,"FIELD_COUNT");var m=new TreeMap<String,String>();String previous="";for(int i=0;i<count;i++){String[] p=new String[2];for(int j=0;j<2;j++){int size=in.readInt();require(size>=0&&size<=131072,"FIELD_SIZE");byte[] b=in.readNBytes(size);require(b.length==size,"TRUNCATED");p[j]=new String(b,StandardCharsets.UTF_8);require(Arrays.equals(b,p[j].getBytes(StandardCharsets.UTF_8)),"UTF8");}require(p[0].compareTo(previous)>0,"NON_CANONICAL_FIELDS");previous=p[0];m.put(p[0],p[1]);}return m;}
    static String packed(Map<String,String> m)throws Exception{return b64(bytes(m));}
    static Map<String,String> unpack(String value)throws Exception{return read(new ByteArrayInputStream(decode(value)));}
    static String password(Path d)throws Exception{return Files.readString(d.resolve("store.pass")).strip();}
    static KeyStore store(Path file,Path d)throws Exception{var s=KeyStore.getInstance("PKCS12");try(var in=Files.newInputStream(file)){s.load(in,password(d).toCharArray());}return s;}
    static PrivateKey key(Path d,String file)throws Exception{return (PrivateKey)store(d.resolve(file),d).getKey("leaf",password(d).toCharArray());}
    static X509Certificate cert(Path d)throws Exception{return (X509Certificate)store(d.resolve("node.p12"),d).getCertificate("leaf");}
    static String identity(X509Certificate c)throws Exception{String id=null;for(var san:c.getSubjectAlternativeNames())if(san.get(0).equals(6)){require(id==null,"AMBIGUOUS_IDENTITY");id=(String)san.get(1);}require(id!=null,"IDENTITY_REQUIRED");return id;}
    static SSLContext tls(Path d,boolean clientKey)throws Exception{var tf=TrustManagerFactory.getInstance("PKIX");tf.init(store(d.resolve("trust.p12"),d));KeyManager[] managers=null;if(clientKey){var kf=KeyManagerFactory.getInstance("SunX509");kf.init(store(d.resolve("node.p12"),d),password(d).toCharArray());var selected=(X509ExtendedKeyManager)kf.getKeyManagers()[0];managers=new KeyManager[]{new X509ExtendedKeyManager(){
        @Override public String chooseClientAlias(String[] types,Principal[] issuers,Socket socket){return "leaf";}
        @Override public String chooseEngineClientAlias(String[] types,Principal[] issuers,SSLEngine engine){return "leaf";}
        @Override public String[] getClientAliases(String type,Principal[] issuers){return selected.getClientAliases(type,issuers);}
        @Override public String[] getServerAliases(String type,Principal[] issuers){return selected.getServerAliases(type,issuers);}
        @Override public String chooseServerAlias(String type,Principal[] issuers,Socket socket){return selected.chooseServerAlias(type,issuers,socket);}
        @Override public X509Certificate[] getCertificateChain(String alias){return selected.getCertificateChain(alias);}
        @Override public PrivateKey getPrivateKey(String alias){return selected.getPrivateKey(alias);}
    }};}var c=SSLContext.getInstance("TLSv1.3");c.init(managers,tf.getTrustManagers(),new SecureRandom());return c;}
    static Map<String,String> call(Path d,String host,int port,Map<String,String> request)throws Exception{return call(d,host,port,request,true);}
    static Map<String,String> call(Path d,String host,int port,Map<String,String> request,boolean clientKey)throws Exception{var raw=new Socket();raw.connect(new InetSocketAddress(host,port),2000);try(var s=(SSLSocket)tls(d,clientKey).getSocketFactory().createSocket(raw,host,port,true)){s.setSoTimeout(host.equals("127.0.0.1")?90000:15000);s.setEnabledProtocols(new String[]{"TLSv1.3"});var p=s.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");s.setSSLParameters(p);s.startHandshake();require(s.getSession().getProtocol().equals("TLSv1.3"),"TLS13_REQUIRED");write(s.getOutputStream(),request);return read(s.getInputStream());}}
    static Map<String,String> control(Path d,Map<String,String> request)throws Exception{var m=new TreeMap<>(request);m.put("nonce",UUID.randomUUID().toString());var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(Files.readAllBytes(d.resolve("control.key")),"HmacSHA256"));m.put("mac",b64(mac.doFinal(bytes(m))));return m;}
    static void admin(Path d,Map<String,String> request,Set<String> seen)throws Exception{String supplied=request.remove("mac");require(supplied!=null,"ADMIN_REQUIRED");var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(Files.readAllBytes(d.resolve("control.key")),"HmacSHA256"));require(MessageDigest.isEqual(mac.doFinal(bytes(request)),decode(supplied)),"ADMIN_INVALID");require(seen.add(request.get("nonce")),"ADMIN_REPLAY");}
    static String signed(Path d,Map<String,String> m)throws Exception{var s=Signature.getInstance("SHA256withECDSA");s.initSign(key(d,"signing.p12"));s.update(bytes(m));return b64(s.sign());}
    static void verify(Path d,Map<String,String> m,String signature)throws Exception{var cf=CertificateFactory.getInstance("X.509");X509Certificate c;try(var in=Files.newInputStream(d.resolve("signing.cer"))){c=(X509Certificate)cf.generateCertificate(in);}var s=Signature.getInstance("SHA256withECDSA");s.initVerify(c.getPublicKey());s.update(bytes(m));require(s.verify(decode(signature)),"SIGNATURE_INVALID");}
    @FunctionalInterface interface Handler { Map<String,String> handle(String peer,Map<String,String> request)throws Exception; }
    static void serve(Path d,String run,Handler handler)throws Exception{var server=(SSLServerSocket)tls(d,true).getServerSocketFactory().createServerSocket(8443);server.setEnabledProtocols(new String[]{"TLSv1.3"});server.setNeedClientAuth(true);while(true){var socket=(SSLSocket)server.accept();Thread.ofVirtual().start(()->{try(socket){socket.setSoTimeout(90000);socket.startHandshake();var peer=(X509Certificate)socket.getSession().getPeerCertificates()[0];require(!REVOKED_PEERS.contains(hash(peer.getEncoded())),"PEER_CREDENTIAL_REVOKED");String id=identity(peer);String prefix="urn:oref:"+run+":";require(id.startsWith(prefix),"RUN_IDENTITY");var request=read(socket.getInputStream());Map<String,String> response;try{response=handler.handle(id.substring(prefix.length()),request);}catch(Exception failure){response=map("code","DENIED","reason",safe(failure));}write(socket.getOutputStream(),response);}catch(Exception failure){REJECTED_PEERS.incrementAndGet();System.out.println("TLS_OR_PROTOCOL_REJECTION "+safe(failure));}});}}
    static String safe(Throwable error){for(Throwable t=error;t!=null;t=t.getCause()){if(t instanceof Rejected)return t.getMessage();if(t instanceof java.sql.SQLException sql)return "SQLSTATE_"+sql.getSQLState();}return error.getClass().getSimpleName();}
    static void prerequisites()throws Exception{var g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));var pair=g.generateKeyPair();var s=Signature.getInstance("SHA256withECDSA");s.initSign(pair.getPrivate());s.update(new byte[]{1});byte[] sig=s.sign();s.initVerify(pair.getPublic());s.update(new byte[]{1});require(s.verify(sig),"SIGN_POSITIVE");s.initVerify(pair.getPublic());s.update(new byte[]{2});require(!s.verify(sig),"SIGN_TAMPER");var t=SSLContext.getInstance("TLSv1.3");t.init(null,null,null);require(Arrays.asList(t.getDefaultSSLParameters().getProtocols()).contains("TLSv1.3"),"TLS13_PROVIDER");System.out.println("PASS TLSv1.3="+t.getProvider().getName()+" P256="+s.getProvider().getName()+" PKIX="+CertPathValidator.getInstance("PKIX").getProvider().getName());}
    static void tool(Path d,String... args)throws Exception{var command=new ArrayList<String>();command.add(Path.of(System.getProperty("java.home"),"bin",System.getProperty("os.name").startsWith("Windows")?"keytool.exe":"keytool").toString());command.addAll(List.of(args));var process=new ProcessBuilder(command).redirectErrorStream(true).start();String output=new String(process.getInputStream().readAllBytes(),StandardCharsets.UTF_8);require(process.waitFor(60,TimeUnit.SECONDS),"KEYTOOL_TIMEOUT");if(process.exitValue()!=0){output=output.replace(password(d),"[REDACTED]");throw new Rejected("KEYTOOL_"+args[0]+":"+output.substring(0,Math.min(1200,output.length())).replace('\n',' '));}}
    static void generate(Path d,String file,String dn,boolean ca)throws Exception{tool(d,"-genkeypair","-alias","leaf","-keyalg","EC","-groupname","secp256r1","-sigalg","SHA256withECDSA","-dname",dn,"-validity","4","-ext",ca?"BC:critical=ca:true,pathlen:0":"BC=ca:false","-ext",ca?"KU:critical=keyCertSign,cRLSign":"KU=digitalSignature","-keystore",d.resolve(file).toString(),"-storepass:file",d.resolve("store.pass").toString());}
    static void prepare(Path root,String run)throws Exception{Files.createDirectories(root);Files.writeString(root.resolve("store.pass"),b64(SecureRandom.getSeed(32)));generate(root,"root.p12","CN=OREF Offline Root",true);tool(root,"-exportcert","-alias","leaf","-keystore",root.resolve("root.p12").toString(),"-storepass:file",root.resolve("store.pass").toString(),"-file",root.resolve("root.cer").toString());var roles=new ArrayList<>(NODES);roles.addAll(List.of("driver","operations-state"));for(String node:roles){Path d=root.resolve(node);Files.createDirectory(d);Files.writeString(d.resolve("store.pass"),b64(SecureRandom.getSeed(32)));Files.write(d.resolve("control.key"),SecureRandom.getSeed(32));Files.copy(root.resolve("root.cer"),d.resolve("root.cer"));generate(d,"node.p12","CN="+node,false);tool(d,"-certreq","-alias","leaf","-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString(),"-file",d.resolve("request.csr").toString());tool(root,"-gencert","-alias","leaf","-keystore",root.resolve("root.p12").toString(),"-storepass:file",root.resolve("store.pass").toString(),"-infile",d.resolve("request.csr").toString(),"-outfile",d.resolve("node.cer").toString(),"-validity","3","-ext","BC=ca:false","-ext","KU=digitalSignature","-ext","EKU=serverAuth,clientAuth","-ext","SAN=DNS:"+node+",DNS:localhost,IP:127.0.0.1,URI:urn:oref:"+run+":"+node);tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());tool(d,"-importcert","-noprompt","-alias","leaf","-file",d.resolve("node.cer").toString(),"-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("trust.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());}
        Path authority=root.resolve("authority");generate(authority,"signing.p12","CN=OREF Operations Authorization",false);tool(authority,"-exportcert","-alias","leaf","-keystore",authority.resolve("signing.p12").toString(),"-storepass:file",authority.resolve("store.pass").toString(),"-file",authority.resolve("signing.cer").toString());for(String node:roles)if(!node.equals("authority"))Files.copy(authority.resolve("signing.cer"),root.resolve(node).resolve("signing.cer"));Path pg=root.resolve("operations-state");pem(pg.resolve("server.key"),"PRIVATE KEY",key(pg,"node.p12").getEncoded());pem(pg.resolve("server.crt"),"CERTIFICATE",cert(pg).getEncoded());System.out.println("Fresh offline root, isolated identities and authority signing key prepared");}
    static void pem(Path file,String type,byte[] bytes)throws Exception{Files.writeString(file,"-----BEGIN "+type+"-----\n"+Base64.getMimeEncoder(64,new byte[]{10}).encodeToString(bytes)+"\n-----END "+type+"-----\n");}
    static void negativeIdentities(Path root,String run)throws Exception{for(String name:List.of("expired-driver","revoked-agent")){Path d=root.resolve(name);Files.createDirectory(d);Files.writeString(d.resolve("store.pass"),b64(SecureRandom.getSeed(32)));Files.copy(root.resolve("root.cer"),d.resolve("root.cer"));generate(d,"node.p12","CN="+name,false);tool(d,"-certreq","-alias","leaf","-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString(),"-file",d.resolve("request.csr").toString());var a=new ArrayList<>(List.of("-gencert","-alias","leaf","-keystore",root.resolve("root.p12").toString(),"-storepass:file",root.resolve("store.pass").toString(),"-infile",d.resolve("request.csr").toString(),"-outfile",d.resolve("node.cer").toString(),"-validity","1","-ext","BC=ca:false","-ext","KU=digitalSignature","-ext","EKU=clientAuth","-ext","SAN=URI:urn:oref:"+run+":"+(name.equals("revoked-agent")?"agent-a":"driver")));if(name.equals("expired-driver"))a.addAll(List.of("-startdate","2020/01/01 00:00:00"));tool(root,a.toArray(String[]::new));tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());tool(d,"-importcert","-noprompt","-alias","leaf","-file",d.resolve("node.cer").toString(),"-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("trust.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());}}
    static void untrustedIdentity(Path root,String run)throws Exception{Path d=root.resolve("untrusted-driver");Files.createDirectory(d);Files.writeString(d.resolve("store.pass"),b64(SecureRandom.getSeed(32)));Files.copy(root.resolve("root.cer"),d.resolve("root.cer"));generate(d,"node.p12","CN=Untrusted OREF Issuer",false);tool(d,"-selfcert","-alias","leaf","-keystore",d.resolve("node.p12").toString(),"-storepass:file",d.resolve("store.pass").toString(),"-validity","3","-ext","SAN=URI:urn:oref:"+run+":driver","-ext","EKU=clientAuth");tool(d,"-importcert","-noprompt","-alias","root","-file",d.resolve("root.cer").toString(),"-keystore",d.resolve("trust.p12").toString(),"-storepass:file",d.resolve("store.pass").toString());}
    public static void main(String[] args)throws Exception{if(args[0].equals("--prerequisites")){prerequisites();return;}if(args[0].equals("--prepare")){prepare(Path.of(args[1]),args[2]);negativeIdentities(Path.of(args[1]),args[2]);untrustedIdentity(Path.of(args[1]),args[2]);return;}throw new Rejected("MODE");}
    private LabOperationsTrust(){ }
}
